function myPow(x: number, n: number): number {
  // Отрицательная степень: x^-n = (1/x)^n.
  // В JS -(-2^31) не переполняется (это double), в отличие от int в Java/C++
  if (n < 0) {
    x = 1 / x;
    n = -n;
  }

  let result = 1;
  // Быстрое возведение в степень: идём по битам n от младшего к старшему,
  // x последовательно принимает значения x, x^2, x^4, x^8, ...
  while (n > 0) {
    // Бит n равен 1 — соответствующая степень x входит в произведение
    if (n % 2 === 1) result *= x;
    x *= x;
    // Не используем >> : для n = 2^31 побитовый сдвиг переполнил бы int32
    n = Math.floor(n / 2);
  }

  return result;
}

// Время: O(log |n|)
// Память: O(1)
